      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": "text_7",
      "quote": "Studies were excluded if they focused exclusively on complicated pediatric populations, such as those with comorbidities that could independently affect post-operative outcomes.",
      "reason": "Notable restrictions (excluding complicated populations, English-only) are stated but no explicit rationale is provided for these restrictions."
    }
